import math

def solve_fixed_point(g, x0, q, tol):
    """Iterate g from x0; stop when q/(1-q)*|x_n - x_(n-1)| < tol. Return (x_n, n)."""
    if q >= 1:
        raise ValueError("not a contraction")
    x, n = x0, 0
    while True:
        x_new = g(x)
        n += 1
        if q / (1 - q) * abs(x_new - x) < tol:
            return x_new, n
        x = x_new

def implied_vol_atm(price):
    """Volatility with 100 * (2 * Phi(sigma / 2) - 1) == price."""
    if not 0 < price < 100:
        raise ValueError("price outside (0, 100)")
    Phi = lambda z: 0.5 * (1 + math.erf(z / math.sqrt(2)))
    M = 100 / math.sqrt(2 * math.pi)        # the largest vega
    T = lambda s: s - (100 * (2 * Phi(s / 2) - 1) - price) / M
    s = 0.1
    for _ in range(100000):
        s_new = T(s)
        if abs(s_new - s) < 1e-13:
            return s_new
        s = s_new
    return s
